import re

def _parse_obs(obs):
    # extract visible objects from observation line
    # patterns: "you see a X, a Y, and a Z." / "you see X." / "nothing."
    m = re.search(r'you see ([^.]+)\.', obs, re.I)
    if not m:
        return []
    text = m.group(1)
    if 'nothing' in text.lower():
        return []
    # split by commas and 'and'
    parts = re.split(r',| and ', text)
    objs = []
    for p in parts:
        p = p.strip().rstrip('.')
        if p and p.lower() != 'nothing':
            objs.append(p)
    return objs

def _parse_goal(goal):
    g = goal.lower()
    # find verb: examine, put, take, etc.
    # object: first noun after verb, e.g. "examine the pillow with the desklamp"
    m = re.search(r'(examine|inspect|look at)\s+(?:the\s+)?(.+?)\s+(?:with|under|on|in|using)\s+(?:the\s+)?(.+)', g)
    if m:
        return m.group(1), m.group(2).strip(), m.group(3).strip()
    m = re.search(r'(put|place)\s+(?:a|an|the)?\s*(.+?)\s+(?:in|on|into)\s+(?:the\s+)?(.+)', g)
    if m:
        return 'put', m.group(2).strip(), m.group(3).strip()
    m = re.search(r'(take|pick up|get)\s+(?:a|an|the)?\s*(.+)', g)
    if m:
        return 'take', m.group(2).strip(), None
    return None, None, None

def solve(env, goal):
    verb, obj, target = _parse_goal(goal)
    if verb is None:
        return env.step('look')

    # Room description gives all receptacles
    room = env.observation
    # receptacles are things like "bed 1", "shelf 2", "drawer 3", "desk 1"
    receptacles = re.findall(r'\b([a-z]+)\s+(\d+)\b', room)
    # build list of receptacle names
    rec_names = []
    seen = set()
    for name, num in receptacles:
        full = f"{name} {num}"
        if full not in seen:
            seen.add(full)
            rec_names.append(full)

    def find_obj_in_obs(obs, wanted):
        # wanted could be "pillow", "pillow 1", "apple", "clean apple"
        w = wanted.lower().replace('clean ', '')
        for o in _parse_obs(obs):
            ol = o.lower()
            if ol == w or ol.startswith(w + ' ') or w in ol:
                return o
        return None

    # Known state cache
    held = None  # object held
    visited = set()

    def go_to(rec):
        return env.step(f'go to {rec}')

    # Try to find target object or receptacle
    # First: if verb is examine, find the object (pillow) then the tool (desklamp) then use it
    if verb in ('examine', 'inspect', 'look at'):
        # find pillow
        obj_found = None
        lamp_found = None
        for rec in rec_names:
            if rec in visited:
                continue
            visited.add(rec)
            fb = go_to(rec)
            # if closed drawer, open it
            if 'is closed' in fb.lower():
                env.step(f'open {rec}')
                fb = env.observation
                if 'you see' in fb.lower():
                    cand = find_obj_in_obs(fb, obj)
                    if cand and obj_found is None:
                        obj_found = cand
                        # take it
                        env.step(f'take {cand} from {rec}')
                        held = cand
                    cand2 = find_obj_in_obs(fb, target)
                    if cand2 and lamp_found is None:
                        lamp_found = cand2
                continue
            if 'you see' in fb.lower():
                cand = find_obj_in_obs(fb, obj)
                if cand and obj_found is None:
                    obj_found = cand
                    env.step(f'take {cand} from {rec}')
                    held = cand
                cand2 = find_obj_in_obs(fb, target)
                if cand2 and lamp_found is None:
                    lamp_found = cand2
            if obj_found and lamp_found:
                break

        # If lamp not found, search again (we may have missed it)
        if lamp_found is None:
            for rec in rec_names:
                fb = go_to(rec)
                if 'is closed' in fb.lower():
                    env.step(f'open {rec}')
                    fb = env.observation
                cand2 = find_obj_in_obs(fb, target)
                if cand2:
                    lamp_found = cand2
                    break
        # turn on lamp
        if lamp_found:
            env.step(f'use {lamp_found}')
        # if object not found, nothing more
        return

    if verb == 'put':
        # find obj and target receptacle
        obj_found = None
        target_rec = None
        # target may be like "fridge" (no number)
        tname = target.lower().split()[0] if target else None
        for rec in rec_names:
            if tname and rec.lower().startswith(tname):
                target_rec = rec
                break
        # find object
        for rec in rec_names:
            if rec == target_rec:
                continue
            fb = go_to(rec)
            if 'is closed' in fb.lower():
                env.step(f'open {rec}')
                fb = env.observation
            cand = find_obj_in_obs(fb, obj)
            if cand:
                obj_found = cand
                env.step(f'take {cand} from {rec}')
                held = cand
                break
        if obj_found and target_rec:
            go_to(target_rec)
            env.step(f'put {obj_found} in {target_rec}')
        return

    if verb == 'take':
        for rec in rec_names:
            fb = go_to(rec)
            if 'is closed' in fb.lower():
                env.step(f'open {rec}')
                fb = env.observation
            cand = find_obj_in_obs(fb, obj)
            if cand:
                env.step(f'take {cand} from {rec}')
                return
        return

    env.step('look')
